def test_pooled_conversion_rate_weights_each_session_equally():
    groups = {
        "small": [{"converted": True}],
        "large": [{"converted": False}, {"converted": None}, {"converted": False}],
        "empty": [],
    }
    assert pooled_conversion_rate(groups) == 0.25


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_pooled_conversion_rate_no_sessions(groups):
    assert pooled_conversion_rate(groups) == 0.0


@pytest.mark.parametrize("days,expected", [(0, 0), (2, 7), (5, 9)])
def test_conversions_in_window(days, expected):
