def test_dedupe_sessions_keeps_last_record_and_sorts_by_day_then_id():
    earlier = {"id": "b", "day": 4, "converted": True}
    later = {"id": "b", "day": 2, "converted": False}
    a = {"id": "a", "day": 2, "converted": True}
    z = {"id": "z", "day": 1, "converted": None}
    assert dedupe_sessions([earlier, later, a, z]) == [z, a, later]


def test_daily_conversion_counts_fills_days_and_ignores_out_of_range_sessions():
